import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const outputDirectory = fileURLToPath(new URL("../icons/", import.meta.url));

const polar = (cx, cy, radius, count, offset = -90) => Array.from({ length: count }, (_, index) => {
  const angle = (index * 360 / count + offset) * Math.PI / 180;
  return [cx + Math.cos(angle) * radius, cy + Math.sin(angle) * radius];
});

function fastener(x, y, accent = "#22d3ee", size = 3.2) {
  const socketRadius = Math.max(1.15, size * .67);
  const socketPoints = polar(0, 0, socketRadius, 6)
    .map(([px, py]) => `${px.toFixed(2)},${py.toFixed(2)}`).join(" ");
  const vertexMarks = polar(0, 0, socketRadius, 6)
    .map(([px, py]) => `<circle cx="${px.toFixed(2)}" cy="${py.toFixed(2)}" r=".28" fill="#94a3b8" opacity=".72"/>`).join("");
  return `<g transform="translate(${x} ${y})" data-detail="hex-socket-screw"><circle r="${size + 2.25}" fill="#020617" stroke="#1e293b" stroke-width=".68"/><circle r="${size + 1.55}" fill="#0f172a" stroke="#334155" stroke-width=".5"/><circle r="${size + .95}" fill="url(#screw-metal)" stroke="#64748b" stroke-width=".62"/><circle r="${size + .35}" fill="none" stroke="#334155" stroke-width=".4" opacity=".65"/><g data-detail="screw-machining-index" fill="none" stroke="#94a3b8" stroke-width=".28" opacity=".72"><circle r="${size + .62}" stroke-dasharray=".8 1.6"/><path d="M0 -${size + 1.25}v.75M0 ${size + 1.25}v-.75M-${size + 1.25} 0h.75M${size + 1.25} 0h-.75"/></g><circle r="${size - .15}" fill="none" stroke="#1e293b" stroke-width=".5"/><polygon points="${socketPoints}" fill="url(#screw-socket)" stroke="#0f172a" stroke-width=".58"/>${vertexMarks}<circle r="${Math.max(.48, size * .23)}" fill="#000" opacity=".92"/><path d="M${-(size + .2)} ${-(size + .2)} 0 ${-(size + .75)}" fill="none" stroke="#fff" stroke-width=".48" stroke-linecap="round" opacity=".46"/><path d="M${-size * .72} ${size * .72}A${size} ${size} 0 0 0 ${size * .72} ${size * .72}" fill="none" stroke="${accent}" stroke-width=".38" opacity=".62"/><circle cx="${size * .5}" cy="${-size * .5}" r=".35" fill="#fff" opacity=".6"/></g>`;
}

function node(x, y, accent, secondary, size = 4) {
  const indexRadius = size + 2.35;
  const contactPoints = polar(0, 0, size + 2.2, 4, 45).map(([px, py]) => `<circle cx="${px.toFixed(2)}" cy="${py.toFixed(2)}" r=".32" fill="#cbd5e1"/>`).join("");
  return `<g transform="translate(${x} ${y})" data-detail="layered-signal-node"><circle r="${size + 3}" fill="#020617" stroke="#475569" stroke-width="1.05"/><circle r="${size + 2.15}" fill="none" stroke="#0f172a" stroke-width=".42"/><circle r="${size + 1.25}" fill="none" stroke="#cbd5e1" stroke-width=".58" stroke-dasharray="2.2 1.5"/><g data-detail="node-calibration-index" stroke="#94a3b8" stroke-width=".4"><path d="M0 -${indexRadius}v1.2M0 ${indexRadius}v-1.2M-${indexRadius} 0h1.2M${indexRadius} 0h-1.2"/></g><g data-detail="node-contact-points">${contactPoints}</g><circle r="${size}" fill="${accent}" stroke="#f8fafc" stroke-width=".78" filter="url(#soft-glow)"/><circle r="${Math.max(1.1, size * .32)}" fill="${secondary}"/><path d="M-${size * .58} ${size * .2}A${size * .65} ${size * .65} 0 0 0 ${size * .2} ${size * .58}" fill="none" stroke="#020617" stroke-width=".34" opacity=".75"/><circle cx="${-size * .32}" cy="${-size * .32}" r=".62" fill="#fff" opacity=".78"/></g>`;
}

function cable(path, accent, secondary, width = 7) {
  return `<g data-detail="refined-signal-conduit"><path d="${path}" fill="none" stroke="#020409" stroke-width="${width + 4}" stroke-linecap="round" stroke-linejoin="round"/><path d="${path}" fill="none" stroke="url(#metal)" stroke-width="${Math.max(4, width - 1)}" stroke-linecap="round" stroke-linejoin="round"/><path d="${path}" fill="none" stroke="#e2e8f0" stroke-width=".82" stroke-linecap="round" stroke-linejoin="round" opacity=".52" transform="translate(-.65 -.65)"/><path class="flow" d="${path}" fill="none" stroke="${accent}" stroke-width="${Math.max(1.35, width * .24)}" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="7 5" filter="url(#soft-glow)"/><path d="${path}" fill="none" stroke="${secondary}" stroke-width=".48" stroke-linecap="round" opacity=".88" transform="translate(.55 .55)"/></g>`;
}

function fiberOpticHarness(accent, secondary) {
  const channels = [
    { name: "inference", y: 68, x: 124, color: accent },
    { name: "privacy", y: 106, x: 128, color: "#a78bfa" },
    { name: "hardware", y: 143, x: 132, color: secondary },
  ];
  const branches = channels.map(({ name, y, x, color }, index) => `<g data-detail="fiber-branch-conduit" data-channel="${name}"><path d="M${x} 96V${y}H142" fill="none" stroke="#020409" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/><path d="M${x} 96V${y}H142" fill="none" stroke="#334155" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round"/><path data-detail="fiber-core" class="flow" d="M${x} 96V${y}H142" fill="none" stroke="${color}" stroke-width=".72" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="3 2" filter="url(#soft-glow)"/><path d="M${x - .45} 94V${y + (y < 96 ? 3 : -3)}" stroke="#f8fafc" stroke-width=".24" opacity=".58"/><g data-detail="fiber-terminal-ferrule"><path d="M137.5 ${y - 4}h6.5v8h-6.5Z" fill="url(#metal)" stroke="#cbd5e1" stroke-width=".46"/><path d="M140 ${y - 2.5}h4v5h-4Z" fill="#020617" stroke="${color}" stroke-width=".34"/><circle class="${index === 1 ? "pulse" : "blink"}" cx="141.2" cy="${y}" r="1.15" fill="${color}" stroke="#f8fafc" stroke-width=".28"/></g></g>`).join("");
  return `<g data-detail="armored-fiber-optic-harness"><g data-detail="fiber-optic-input-coupler"><path d="M107 96h10" stroke="#020409" stroke-width="5.2" stroke-linecap="round"/><path d="M108 96h9" stroke="url(#metal)" stroke-width="2.7" stroke-linecap="round"/><path class="flow" d="M109 96h8" stroke="url(#accent)" stroke-width=".82" stroke-dasharray="3 2"/><circle cx="116" cy="96" r="7.2" fill="#020409" stroke="#94a3b8" stroke-width=".62"/><circle class="mechanical" cx="116" cy="96" r="5.1" fill="url(#metal)" stroke="${accent}" stroke-width=".48" stroke-dasharray="2 1"/><circle cx="116" cy="96" r="2.2" fill="${secondary}" stroke="#f8fafc" stroke-width=".38"/></g><g data-detail="fiber-distribution-manifold"><path d="M119 61h15l5 6v77l-5 7h-15l-5-7V67Z" fill="url(#dark-metal)" stroke="#cbd5e1" stroke-width=".72"/><path d="M121 66h11l3 4v70l-3 5h-11l-3-5V70Z" fill="#020617" stroke="#475569" stroke-width=".44"/><path d="M121 72h14M121 135h14" stroke="#f8fafc" stroke-width=".3" opacity=".65"/><g data-detail="fiber-backbone-window">${channels.map(({ y, x, color })=>`<path d="M${x} 76v${Math.max(7,Math.abs(y-96)-5)}" stroke="${color}" stroke-width=".6" stroke-linecap="round" opacity=".72"/><circle cx="${x}" cy="96" r="1.1" fill="${color}" stroke="#f8fafc" stroke-width=".24"/>`).join("")}</g></g>${branches}<g data-detail="fiber-strain-relief-clamps">${[82,126].map((y,index)=>`<g><path d="M115 ${y - 3}h23l3 3-3 3h-23l-3-3Z" fill="url(#dark-metal)" stroke="#94a3b8" stroke-width=".42"/><path d="M119 ${y - 1.5}h17v3h-17Z" fill="#020617" stroke="${index ? secondary : accent}" stroke-width=".3"/>${fastener(116,y,index ? secondary : accent,.58)}${fastener(138,y,index ? accent : secondary,.58)}</g>`).join("")}</g><g data-detail="fiber-optic-status-prism"><path d="m128 88 7 4v8l-7 4-7-4v-8Z" fill="#020617" stroke="#e2e8f0" stroke-width=".5"/><path d="m128 91 4 2.2v4.6l-4 2.2-4-2.2v-4.6Z" fill="url(#glass)" stroke="${accent}" stroke-width=".38"/><circle class="pulse" cx="128" cy="95.5" r="1.2" fill="${secondary}" stroke="#fff" stroke-width=".25"/></g></g>`;
}

function plinth(accent, secondary, width = 128, y = 158) {
  const x = 100 - width / 2;
  return `<g data-detail="precision-equipment-plinth"><ellipse cx="100" cy="${y + 15}" rx="${width * .56}" ry="7.2" fill="#000" opacity=".42"/><path d="M${x} ${y}h${width}l9 7-9 9H${x}l-9-9Z" fill="url(#dark-metal)" stroke="#64748b" stroke-width="1.18"/><path d="M${x + 8} ${y + 3}h${width - 16}" stroke="#f8fafc" stroke-width=".86" opacity=".68"/><path d="M${x + 12} ${y + 6}h${width - 24}" stroke="#334155" stroke-width=".62" stroke-dasharray="3 2"/><path d="M${x + 18} ${y + 11}h${width - 36}" stroke="${accent}" stroke-width="1.62" filter="url(#soft-glow)"/><path d="M${x + 28} ${y + 14}h${width - 56}" stroke="${secondary}" stroke-width=".48" opacity=".82"/><g data-detail="plinth-machined-joints" stroke="#94a3b8" stroke-width=".38" opacity=".72"><path d="M${x + 16} ${y + 4}v8M${x + width - 16} ${y + 4}v8M${x + width / 2 - 8} ${y + 3}h16"/></g>${fastener(x + 8, y + 8, accent, 1.2)}${fastener(x + width - 8, y + 8, secondary, 1.2)}</g>`;
}

function chassisPlinthMounts(accent, secondary) {
  const mount = (x, color, mirrored = false) => `<g data-detail="load-bearing-foot" transform="translate(${x} 0)${mirrored ? " scale(-1 1)" : ""}"><path d="M-6 137h12l4 5v14l-4 5H-6l-4-5v-14Z" fill="#020409" stroke="#334155" stroke-width=".72"/><path d="M-3 138h6l2.8 4v14L3 159h-6l-2.8-3v-14Z" fill="url(#metal)" stroke="#cbd5e1" stroke-width=".52"/><path d="M0 140v16" stroke="${color}" stroke-width=".62" filter="url(#soft-glow)"/><path d="M-4 143h8m-8 10h8" stroke="#0f172a" stroke-width=".44"/><path d="M-8 157h16l5 5H-13Z" fill="url(#dark-metal)" stroke="#94a3b8" stroke-width=".52"/><path d="M-5 159h10" stroke="#f8fafc" stroke-width=".3" opacity=".72"/>${fastener(0,144,color,.72)}</g>`;
  return `<g data-detail="chassis-to-plinth-mounts" data-mounting-system="dual-load-bearing"><path d="M54 139 45 150v10M146 139l9 11v10" fill="none" stroke="#020409" stroke-width="4.2" stroke-linecap="round"/><path d="M54 140 47 151v8M146 140l7 11v8" fill="none" stroke="url(#metal)" stroke-width="1.2" stroke-linecap="round"/><path d="M49 149h10m82 0h10" stroke="#cbd5e1" stroke-width=".38"/>${mount(55,accent)}${mount(145,secondary,true)}<g data-detail="mounting-load-path-index" stroke="#94a3b8" stroke-width=".3" opacity=".72"><path d="M50 135h10m80 0h10M46 163h18m72 0h18"/></g></g>`;
}

function socket(x, y, accent, secondary, radius = 8) {
  const pins = polar(x, y, radius - 2, 4, -45)
    .map(([px, py]) => `<circle cx="${px.toFixed(2)}" cy="${py.toFixed(2)}" r="1.25" fill="#e2e8f0"/>`).join("");
  return `<g data-detail="keyed-interface-socket"><circle cx="${x}" cy="${y}" r="${radius + 4}" fill="#020409" stroke="#475569" stroke-width="1.18"/><circle cx="${x}" cy="${y}" r="${radius + 2.2}" fill="none" stroke="#cbd5e1" stroke-width=".58" stroke-dasharray="3 1.7"/><g data-detail="interface-lock-tabs" stroke="#94a3b8" stroke-width=".42"><path d="M${x} ${y-radius-3.1}v1.5M${x} ${y+radius+3.1}v-1.5M${x-radius-3.1} ${y}h1.5M${x+radius+3.1} ${y}h-1.5"/></g><circle cx="${x}" cy="${y}" r="${radius + 1}" fill="url(#metal)" stroke="#f8fafc" stroke-width=".68"/><circle cx="${x}" cy="${y}" r="${radius - .35}" fill="none" stroke="${secondary}" stroke-width=".34" stroke-dasharray="1.4 2.1"/><circle cx="${x}" cy="${y}" r="${radius - 2}" fill="#040a13" stroke="${accent}" stroke-width="1.12"/>${pins}<path d="M${x - 2.5} ${y - radius - 1}h5" stroke="#020617" stroke-width=".92"/><circle cx="${x}" cy="${y}" r="2.3" fill="${secondary}"/><circle cx="${x - .7}" cy="${y - .7}" r=".65" fill="#fff" opacity=".8"/></g>`;
}

function vents(x, y, count, accent, vertical = false) {
  const spacing = 6;
  const railWidth = (count - 1) * spacing + 10;
  const plateX = x - 5;
  const plateY = y - 4;
  const slits = Array.from({ length: count }, (_, index) => {
    const xx = x + index * spacing;
    const signal = index === 0 || index === count - 1 || index % 5 === 0;
    return `<rect x="${xx - 1.25}" y="${y}" width="2.5" height="10" rx="1.15" fill="#020409" stroke="#334155" stroke-width=".45"/><path d="M${xx} ${y + 1.5}v7" stroke="${signal ? accent : "#94a3b8"}" stroke-width=".8" stroke-linecap="round"/><path d="M${xx - .55} ${y + 1.7}v5.8" stroke="#fff" stroke-width=".3" opacity=".45"/>`;
  }).join("");
  const rail = `<g><path d="M${plateX + 4} ${plateY}H${plateX + railWidth - 4}L${plateX + railWidth} ${plateY + 4}V${plateY + 14}L${plateX + railWidth - 4} ${plateY + 18}H${plateX + 4}L${plateX} ${plateY + 14}V${plateY + 4}Z" fill="#07101c" stroke="#475569" stroke-width=".72"/><path d="M${plateX + 5} ${plateY + 2}H${plateX + railWidth - 5}" stroke="#cbd5e1" stroke-width=".4" opacity=".65"/><path d="M${plateX + 5} ${plateY + 16}H${plateX + railWidth - 5}" stroke="${accent}" stroke-width=".4" opacity=".7"/><g data-detail="cooling-rail-mounts" fill="#020617" stroke="#94a3b8" stroke-width=".3"><circle cx="${plateX + 4}" cy="${plateY + 5}" r=".75"/><circle cx="${plateX + railWidth - 4}" cy="${plateY + 5}" r=".75"/><circle cx="${plateX + 4}" cy="${plateY + 13}" r=".75"/><circle cx="${plateX + railWidth - 4}" cy="${plateY + 13}" r=".75"/></g>${slits}</g>`;
  return `<g data-detail="mounted-cooling-rail"${vertical ? ` transform="rotate(90 ${x} ${y})"` : ""}>${rail}</g>`;
}

function tickRing(cx, cy, radius, count, accent, secondary, length = 6) {
  return `<g data-detail="calibration-ring"><circle cx="${cx}" cy="${cy}" r="${radius - 1.35}" fill="none" stroke="#64748b" stroke-width=".32" stroke-dasharray=".8 2.2" opacity=".68"/>${Array.from({ length: count }, (_, index) => {
    const angle = index * 360 / count;
    return `<path d="M${cx} ${cy - radius}v${length}" transform="rotate(${angle} ${cx} ${cy})" stroke="${index % 4 === 0 ? accent : index % 2 === 0 ? secondary : "#64748b"}" stroke-width="${index % 4 === 0 ? 2.4 : 1.25}" stroke-linecap="round"/>`;
  }).join("")}</g>`;
}

function moduleCard(id, x, y, width, height, accent, secondary, active = true) {
  return `<g data-detail="etched-hardware-module" filter="url(#shadow)"><path d="M${x + 9} ${y}H${x + width - 9}L${x + width} ${y + 9}V${y + height - 9}L${x + width - 9} ${y + height}H${x + 9}L${x} ${y + height - 9}V${y + 9}Z" fill="url(#dark-metal)" stroke="#94a3b8" stroke-width="1.4"/><path d="M${x + 10} ${y + 4}H${x + width - 10}" stroke="#f8fafc" stroke-width=".58" opacity=".75"/><path d="M${x + 10} ${y + 7}H${x + width - 10}" stroke="${active ? accent : "#475569"}" stroke-width="1.42"/><path d="M${x + 8} ${y + 12}V${y + height - 11}M${x + width - 7} ${y + 12}V${y + height - 11}" stroke="#334155" stroke-width=".58" stroke-dasharray="2 2"/><path d="M${x + 12} ${y + height * .46}H${x + width - 21}M${x + 12} ${y + height * .7}H${x + width - 29}" stroke="#cbd5e1" stroke-width="1.3" stroke-linecap="round"/><path d="M${x + 12} ${y + height * .58}h${Math.max(4, width - 43)}" stroke="#64748b" stroke-width=".58"/><g data-detail="module-contact-pads" fill="${active ? accent : "#475569"}" stroke="#cbd5e1" stroke-width=".25"><rect x="${x + 11}" y="${y + height - 7}" width="2.4" height="1.5" rx=".35"/><rect x="${x + 16}" y="${y + height - 7}" width="2.4" height="1.5" rx=".35"/><rect x="${x + 21}" y="${y + height - 7}" width="2.4" height="1.5" rx=".35"/></g>${fastener(x + 5, y + height / 2, accent, 1)}<circle cx="${x + width - 13}" cy="${y + height * .5}" r="4" fill="${active ? secondary : "#334155"}" stroke="#f8fafc" stroke-width=".72"/><circle cx="${x + width - 13}" cy="${y + height * .5}" r="2.1" fill="#020617"/><circle cx="${x + width - 13}" cy="${y + height * .75}" r="2.2" fill="${active ? accent : "#475569"}" stroke="#fff" stroke-width=".48"/></g>`;
}

function memoryLayer(y, accent, secondary, index) {
  const cx = 92;
  const rx = 40;
  const ry = 12;
  const depth = 22;
  const layerAccent = index === 1 ? secondary : accent;
  const indexMarks = Array.from({ length: 7 }, (_, mark) => {
    const x = 62 + mark * 10;
    return `<path d="M${x} ${y + depth - 2}v4" stroke="${mark % 3 === 0 ? layerAccent : "#94a3b8"}" stroke-width=".52"/>`;
  }).join("");
  const healthCells = Array.from({ length: 5 }, (_, cell) => `<rect x="${cx - 12 + cell * 5.5}" y="${y + depth - 2.2}" width="3.4" height="2.7" rx=".55" fill="${cell <= 3 - index ? layerAccent : "#1e293b"}" stroke="#cbd5e1" stroke-width=".22"/>`).join("");
  return `<g data-detail="memory-layer" data-layer="${index}"><ellipse data-detail="layer-machined-cap" cx="${cx}" cy="${y}" rx="${rx}" ry="${ry}" fill="url(#metal)" stroke="#f8fafc" stroke-width="1.08"/><ellipse cx="${cx}" cy="${y}" rx="${rx - 4.5}" ry="${ry - 2.7}" fill="#07101d" stroke="${layerAccent}" stroke-width=".96"/><path data-detail="layer-cap-highlight" d="M${cx - 30} ${y - 3.5}c14-6 46-6 60 0" fill="none" stroke="#f8fafc" stroke-width=".48" opacity=".82"/><path d="M${cx - rx} ${y}v${depth}c0 8 18 13 40 13s40-5 40-13V${y}" fill="url(#dark-metal)" stroke="${layerAccent}" stroke-width="1.22"/><path data-detail="layer-side-seams" d="M${cx - rx + 7} ${y + 5}c16 6 50 6 66 0M${cx - rx + 5} ${y + 15}c18 7 54 7 70 0" fill="none" stroke="#cbd5e1" stroke-width=".56" stroke-dasharray="5 3" opacity=".78"/><ellipse cx="${cx}" cy="${y + depth}" rx="${rx}" ry="${ry}" fill="url(#glass)" stroke="${layerAccent}" stroke-width="1.12"/><ellipse cx="${cx}" cy="${y + depth}" rx="${rx - 7.5}" ry="${ry - 3.6}" fill="none" stroke="#94a3b8" stroke-width=".52" stroke-dasharray="3 2"/><g data-detail="layer-data-window"><path d="M${cx - 16} ${y + depth - 5.2}h32l3 2.8v5.6l-3 2.8h-32l-3-2.8v-5.6Z" fill="#020617" stroke="${layerAccent}" stroke-width=".42"/>${healthCells}<path d="M${cx - 12} ${y + depth + 2.5}h24" stroke="#64748b" stroke-width=".28"/></g><g data-detail="layer-address-index">${indexMarks}</g>${fastener(cx - 29, y + depth, layerAccent, .92)}${fastener(cx + 29, y + depth, secondary, .92)}</g>`;
}

function memoryRetentionDetails(accent, secondary) {
  const gates = [68, 96, 124].map((y, index) => `<g data-detail="retention-gate" data-gate="${index}"><path d="M49 ${y - 6.5}h8.5v13H49l-4-6.5Z" fill="url(#metal)" stroke="${index === 1 ? secondary : accent}" stroke-width=".68"/><path d="M135 ${y - 6.5}h-8.5v13h8.5l4-6.5Z" fill="url(#metal)" stroke="${index === 1 ? accent : secondary}" stroke-width=".68"/><path d="M50.5 ${y - 3.4}v6.8m83-6.8v6.8" stroke="#020617" stroke-width=".82"/><path d="M53 ${y}h5m68 0h5" stroke="#e2e8f0" stroke-width=".38"/><circle cx="52" cy="${y - 4.2}" r=".85" fill="${index === 2 ? "#fbbf24" : accent}" stroke="#fff" stroke-width=".22"/><circle cx="132" cy="${y - 4.2}" r=".85" fill="${index === 1 ? secondary : accent}" stroke="#fff" stroke-width=".22"/></g>`).join("");
  return `<g data-detail="retention-gates">${gates}</g><g data-detail="encrypted-memory-core"><path data-detail="core-key-cage" d="m92 75 13 7.5v15L92 105l-13-7.5v-15Z" fill="#020617" stroke="#e2e8f0" stroke-width=".68" stroke-dasharray="3 2"/><circle cx="92" cy="90" r="9.2" fill="url(#glass)" stroke="${accent}" stroke-width=".72"/><circle class="mechanical" cx="92" cy="90" r="7.1" fill="none" stroke="${secondary}" stroke-width=".42" stroke-dasharray="2 1.5"/><path d="M88 88v-2a4 4 0 0 1 8 0v2m-9 0h10v8H87Z" fill="#020617" stroke="${secondary}" stroke-width=".72"/><circle cx="92" cy="92" r="1.2" fill="#f8fafc"/><g data-detail="core-integrity-beacons">${[[92,79],[103,90],[92,101],[81,90]].map(([x,y],i)=>`<circle class="${i === 0 ? "blink" : ""}" cx="${x}" cy="${y}" r="1.05" fill="${i % 2 ? secondary : accent}" stroke="#fff" stroke-width=".24"/>`).join("")}</g></g>`;
}

function memoryArchiveCartridges(accent, secondary) {
  return `<g data-detail="archive-cartridges">${[76, 98, 120].map((y, index) => `<g data-detail="archive-cartridge" data-cartridge="${index}"><path d="M143 ${y}h18l4 4v9l-3 3h-19Z" fill="#030914" stroke="${index === 1 ? accent : secondary}" stroke-width=".62"/><path d="M146 ${y + 3}h11m-11 4h8" stroke="#e2e8f0" stroke-width=".46"/><g data-detail="archive-media-window"><rect x="146" y="${y + 10}" width="11" height="3" rx=".65" fill="#020617" stroke="#64748b" stroke-width=".28"/><path d="M148 ${y + 11.5}h${index === 2 ? 4 : 7}" stroke="${index === 1 ? secondary : accent}" stroke-width=".42"/></g><g data-detail="cartridge-contact-bank" stroke="#cbd5e1" stroke-width=".24"><path d="M145 ${y + 15}v2m4-2v2m4-2v2"/></g><circle class="${index < 2 ? "blink" : ""}" cx="162" cy="${y + 7}" r="1.45" fill="${index === 2 ? "#fbbf24" : index === 1 ? secondary : accent}" stroke="#fff" stroke-width=".28"/></g>`).join("")}</g>`;
}

function activityLane(y, accent, secondary, positions) {
  const packets = positions.map((x, index) => `<g data-event="${index}"><path d="M${x - 4} ${y - 5}h8l3 3v4l-3 3h-8l-3-3v-4Z" fill="#07101d" stroke="${index % 2 ? secondary : accent}" stroke-width=".8"/><circle cx="${x}" cy="${y}" r="1.4" fill="${index % 2 ? accent : secondary}"/><path d="M${x - 2} ${y - 2}h4" stroke="#f8fafc" stroke-width=".45"/></g>`).join("");
  return `<g data-detail="temporal-event-lane"><path d="M52 ${y}h96" stroke="#020409" stroke-width="4.6" stroke-linecap="round"/><path d="M53 ${y}h94" stroke="#334155" stroke-width="1.25" stroke-linecap="round"/><path class="flow" d="M53 ${y}h94" stroke="${accent}" stroke-width=".7" stroke-dasharray="5 5"/>${packets}</g>`;
}

function capabilitySlot(y, state, accent, secondary) {
  const statusSymbol = state === "probed"
    ? `<circle cx="66" cy="${y + 13}" r="7" fill="#020617" stroke="${accent}" stroke-width=".9"/><circle class="blink" cx="66" cy="${y + 13}" r="2" fill="${secondary}"/><circle cx="66" cy="${y + 13}" r="4.5" fill="none" stroke="#64748b" stroke-width=".45" stroke-dasharray="2 1.5"/><path d="M66 ${y + 3}v4m0 12v4M56 ${y + 13}h4m12 0h4" stroke="#e2e8f0" stroke-width=".65"/>`
    : state === "ready"
      ? `<path d="m66 ${y + 2} 11 6v12l-11 6-11-6v-12Z" fill="#03120f" stroke="${accent}" stroke-width=".75"/><path d="m59 ${y + 13} 5 5 10-12" fill="none" stroke="#4ade80" stroke-width="2" stroke-linecap="round"/><path d="M61 ${y + 21}h10" stroke="#94a3b8" stroke-width=".45"/>`
      : `<path d="M57 ${y + 6}h18v15H57Z" fill="#020617" stroke="${secondary}" stroke-width=".85" stroke-dasharray="3 2"/><path d="M60 ${y + 10}h11m-11 4h8m-8 4h12" stroke="#94a3b8" stroke-width=".6"/><circle cx="72" cy="${y + 9}" r="1.1" fill="${secondary}"/>`;
  return `<g data-detail="capability-slot" data-state="${state}"><path d="M55 ${y}h90l7 7v12l-7 7H55l-7-7V${y + 7}Z" fill="url(#dark-metal)" stroke="#94a3b8" stroke-width="1.05"/><path d="M58 ${y + 3}h84" stroke="#e2e8f0" stroke-width=".4" opacity=".65"/>${statusSymbol}<g data-detail="capability-slot-telemetry"><path d="M84 ${y + 8}h49M84 ${y + 14}h37M84 ${y + 20}h44" stroke="#64748b" stroke-width=".8"/><path d="M85 ${y + 8}h${state === "ready" ? 41 : state === "probed" ? 29 : 18}" stroke="${state === "planned" ? secondary : accent}" stroke-width=".9"/><path class="flow" d="M85 ${y + 20}h${state === "ready" ? 35 : state === "probed" ? 24 : 12}" stroke="${state === "ready" ? "#4ade80" : secondary}" stroke-width=".55" stroke-dasharray="3 2"/></g><g data-detail="capability-state-lamp"><circle cx="141" cy="${y + 13}" r="4.2" fill="#020617" stroke="#64748b" stroke-width=".55"/><circle class="blink" cx="141" cy="${y + 13}" r="2.3" fill="${state === "ready" ? "#4ade80" : state === "probed" ? accent : "#475569"}" stroke="#f8fafc" stroke-width=".45"/></g>${fastener(52, y + 13, accent, .9)}</g>`;
}

function plannerCandidate(cx, y, accent, secondary, selected = false) {
  return `<g data-detail="action-candidate" data-selected="${selected}"><path d="m${cx} ${y - 18} 20 11v22l-20 11-20-11V${y - 7}Z" fill="${selected ? "url(#glass)" : "url(#dark-metal)"}" stroke="${selected ? accent : "#94a3b8"}" stroke-width="1.35"/><path d="M${cx - 10} ${y - 6}h20M${cx - 10} ${y}h${selected ? 16 : 11}M${cx - 10} ${y + 6}h${selected ? 12 : 7}" stroke="${selected ? "#f8fafc" : "#64748b"}" stroke-width="1"/><circle cx="${cx + 11}" cy="${y + 7}" r="3" fill="${selected ? secondary : "#334155"}" stroke="#fff" stroke-width=".55"/>${fastener(cx, y - 13, accent, 1)}</g>`;
}

function evidenceNode(x, y, accent, secondary, index) {
  return `<g data-detail="evidence-link" data-index="${index}"><path d="m${x} ${y - 8} 7 4v8l-7 4-7-4v-8Z" fill="url(#dark-metal)" stroke="${index % 2 ? secondary : accent}" stroke-width=".9"/><circle cx="${x}" cy="${y}" r="2" fill="${index % 2 ? accent : secondary}" stroke="#fff" stroke-width=".5"/><path d="M${x - 3} ${y - 4}h6" stroke="#f8fafc" stroke-width=".45"/></g>`;
}

function kinematicJoint(x, y, accent, secondary, size = 3.2) {
  return `<g data-detail="articulated-bearing" class="blink" transform="translate(${x} ${y})"><circle r="${size + 2.2}" fill="#020409" stroke="#64748b" stroke-width=".68"/><circle data-detail="bearing-retainer-ring" r="${size + 1.25}" fill="none" stroke="#94a3b8" stroke-width=".34" stroke-dasharray="1.2 1.5"/><circle r="${size}" fill="url(#metal)" stroke="#e2e8f0" stroke-width=".58"/><circle r="${Math.max(1.2, size - 1.6)}" fill="${accent}" stroke="${secondary}" stroke-width=".48"/><path d="M-${size + 1} 0h${(size + 1) * 2}M0 -${size + 1}v${(size + 1) * 2}" stroke="#020617" stroke-width=".4" opacity=".8"/><circle cx="${size * .48}" cy="${-size * .48}" r=".3" fill="#f8fafc" opacity=".75"/></g>`;
}

function statusCell(x, y, width, accent, secondary, active = true) {
  return `<g data-detail="precision-status-cell"><path d="M${x} ${y}h${width - 5}l5 5v10l-5 5H${x}Z" fill="#030914" stroke="${active ? accent : "#475569"}" stroke-width=".68"/><path d="M${x + 5} ${y + 6}h${width - 18}m-${width - 18} 5h${Math.max(6, width - 25)}" stroke="#94a3b8" stroke-width=".5"/><g data-detail="status-cell-contacts" fill="${active ? accent : "#475569"}" stroke="#cbd5e1" stroke-width=".22"><circle cx="${x + 4}" cy="${y + 16}" r=".65"/><circle cx="${x + 8}" cy="${y + 16}" r=".65"/></g><circle class="${active ? "blink" : ""}" cx="${x + width - 8}" cy="${y + 10}" r="2" fill="${active ? secondary : "#334155"}" stroke="#f8fafc" stroke-width=".4"/><circle cx="${x + width - 8}" cy="${y + 10}" r="2.8" fill="none" stroke="#475569" stroke-width=".3" stroke-dasharray="1 1"/></g>`;
}

function lockedControlPair(x, y, accent, secondary, index) {
  const firstKnobY = index === 1 ? y + 9 : y + 12;
  const secondKnobY = index === 3 ? y + 10 : y + 13;
  return `<g data-detail="locked-control-pair" data-channels="${index * 2 + 1}-${index * 2 + 2}" data-state="locked-read-only"><path d="M${x + 3} ${y}h12l3 3v10l-3 3h-12l-3-3V${y + 3}Z" fill="#07101d" stroke="${index % 2 ? secondary : accent}" stroke-width=".64"/><path d="M${x + 6} ${y + 4}v9m6-9v9" stroke="#475569" stroke-width="1.05" stroke-linecap="round"/><g data-detail="control-guide-index" stroke="#94a3b8" stroke-width=".28"><path d="M${x + 4.6} ${y + 6}h2.8m-2.8 4h2.8m4.2-4h2.8m-2.8 4h2.8"/></g><circle cx="${x + 6}" cy="${firstKnobY}" r="1.7" fill="#020617" stroke="#cbd5e1" stroke-width=".45"/><circle cx="${x + 12}" cy="${secondKnobY}" r="1.7" fill="#020617" stroke="#cbd5e1" stroke-width=".45"/><circle class="blink" cx="${x + 15}" cy="${y + 3}" r="1.15" fill="${index === 1 ? "#f59e0b" : "#475569"}" stroke="#f8fafc" stroke-width=".32"/></g>`;
}

function gearAxisSupport(cx, accent, secondary) {
  return `<g data-detail="gear-axis-support" data-purpose="supports-gear-axis-and-absorbs-vibration"><path d="M${cx - 12} 138h24l4.5 5.5V159h-33v-15.5Z" fill="url(#dark-metal)" stroke="#94a3b8" stroke-width=".78"/><path d="M${cx - 8.5} 140.5h17l3 4.2v11.5h-23v-11.5Z" fill="#020617" stroke="#475569" stroke-width=".48"/><path d="M${cx - 6} 142v12m12-12v12" stroke="${accent}" stroke-width=".52" opacity=".78"/><path d="M${cx - 10} 157h20" stroke="${secondary}" stroke-width=".55"/><g data-detail="vibration-damping-coupler"><circle cx="${cx}" cy="150" r="5.3" fill="#020409" stroke="#cbd5e1" stroke-width=".62"/><circle cx="${cx}" cy="150" r="3.5" fill="url(#metal)" stroke="${accent}" stroke-width=".48"/><circle cx="${cx}" cy="150" r="1.7" fill="#07111e" stroke="${secondary}" stroke-width=".42"/><path d="M${cx - 2.3} 150h4.6M${cx} 147.7v4.6" stroke="#f8fafc" stroke-width=".3" opacity=".72"/></g><g data-detail="support-load-index" stroke="#cbd5e1" stroke-width=".3" opacity=".75"><path d="M${cx - 9} 144h3m12 0h3M${cx - 9} 154h3m12 0h3"/></g>${fastener(cx - 12,156,accent,.62)}${fastener(cx + 12,156,secondary,.62)}</g>`;
}

function detailedGear(cx, cy, radius, accent, secondary) {
  const toothCount = 16;
  const teeth = Array.from({ length: toothCount }, (_, index) => `<g data-detail="chamfered-gear-tooth" transform="rotate(${index * 360 / toothCount} ${cx} ${cy})"><path d="M${cx - 4.1} ${cy - radius - 1}l.8-7.2 1.6-2.1h3.4l1.6 2.1.8 7.2-2.4 2.6h-3.4Z" fill="url(#metal)" stroke="#dbeafe" stroke-width=".72"/><path d="M${cx - 1.65} ${cy - radius - 7.8}h3.3" stroke="#fff" stroke-width=".48" opacity=".78"/><path d="M${cx - 2.8} ${cy - radius - 1.4}h5.6" stroke="${index % 2 ? secondary : accent}" stroke-width=".46" opacity=".72"/></g>`).join("");
  const spokes = Array.from({ length: 8 }, (_, index) => `<g transform="rotate(${index * 45} ${cx} ${cy})"><path d="M${cx - 2.9} ${cy - radius + 9.5}l1.35 17h3.1l1.35-17-2.9-3Z" fill="#020409" stroke="#64748b" stroke-width=".55"/><path d="M${cx - 1.5} ${cy - radius + 10.2}l.8 15.2h1.4l.8-15.2-1.5-1.65Z" fill="url(#metal)" stroke="#e2e8f0" stroke-width=".42"/><path d="M${cx} ${cy - radius + 11.2}v13" stroke="${index % 2 ? secondary : accent}" stroke-width=".42" opacity=".72"/></g>`).join("");
  const limiterPins = polar(cx, cy, radius * .69, 6).map(([x, y], index) => `<g data-detail="torque-limiter-pin" transform="translate(${x.toFixed(2)} ${y.toFixed(2)})"><circle r="3.05" fill="#020409" stroke="#64748b" stroke-width=".55"/><circle r="2.05" fill="url(#metal)" stroke="#e2e8f0" stroke-width=".46"/><path d="M-1.15 0h2.3" stroke="${index % 2 ? secondary : accent}" stroke-width=".55"/><circle cx="-.55" cy="-.65" r=".42" fill="#fff" opacity=".7"/></g>`).join("");
  const bearingBalls = polar(cx, cy, 18.7, 12).map(([x, y], index) => `<circle data-detail="bearing-ball" cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="1.65" fill="${index % 3 === 0 ? accent : "url(#metal)"}" stroke="#e2e8f0" stroke-width=".34"/>`).join("");
  const encoderTicks = Array.from({ length: 32 }, (_, index) => `<path d="M${cx} ${cy - radius + 4.8}v${index % 4 === 0 ? 2.8 : 1.65}" transform="rotate(${index * 11.25} ${cx} ${cy})" stroke="${index % 8 === 0 ? secondary : index % 4 === 0 ? accent : "#94a3b8"}" stroke-width="${index % 4 === 0 ? .58 : .36}"/>`).join("");
  const rotor = polar(cx, cy, 13.4, 8).map(([x, y]) => `${x.toFixed(2)},${y.toFixed(2)}`).join(" ");
  const shaftSpline = Array.from({ length: 16 }, (_, index) => {
    const angle = -Math.PI / 2 + index * Math.PI / 8;
    const splineRadius = index % 2 === 0 ? 7.35 : 6.1;
    return `${(cx + Math.cos(angle) * splineRadius).toFixed(2)},${(cy + Math.sin(angle) * splineRadius).toFixed(2)}`;
  }).join(" ");
  const aperture = polar(cx, cy, 4.55, 6).map(([x, y]) => `${x.toFixed(2)},${y.toFixed(2)}`).join(" ");
  return `<g data-gear="primary"><circle cx="${cx}" cy="${cy + 4}" r="${radius + 7}" fill="#000" opacity=".45" filter="url(#shadow)"/><g data-detail="precision-gear-rotor" class="mechanical"><g data-detail="chamfered-gear-teeth">${teeth}</g><circle data-detail="gear-root-collar" cx="${cx}" cy="${cy}" r="${radius + 1.5}" fill="url(#metal)" stroke="#f8fafc" stroke-width="1.15"/><circle cx="${cx}" cy="${cy}" r="${radius - 1.8}" fill="#07111e" stroke="#475569" stroke-width=".75"/><circle cx="${cx}" cy="${cy}" r="${radius - 4.1}" fill="none" stroke="#cbd5e1" stroke-width=".42"/><g data-detail="optical-encoder-ring">${encoderTicks}<circle cx="${cx}" cy="${cy}" r="${radius - 7.7}" fill="none" stroke="${accent}" stroke-width=".55" stroke-dasharray="11 3 2 3" opacity=".82"/></g><circle cx="${cx}" cy="${cy}" r="${radius - 10}" fill="url(#glass)" stroke="#64748b" stroke-width=".7"/><g data-detail="tapered-torque-spokes">${spokes}</g><g data-detail="torque-limiter-pins">${limiterPins}</g><g data-detail="lubrication-microchannels" fill="none" stroke="#94a3b8" stroke-width=".38" opacity=".8"><path d="M${cx - 31} ${cy - 9}a32 32 0 0 1 7-13"/><path d="M${cx + 24} ${cy + 22}a32 32 0 0 1-7 7"/></g></g><g data-detail="fixed-drive-hub"><circle data-detail="dual-bearing" cx="${cx}" cy="${cy}" r="22.8" fill="#020409" stroke="#94a3b8" stroke-width="1.15"/><circle cx="${cx}" cy="${cy}" r="20.9" fill="none" stroke="#e2e8f0" stroke-width=".42"/><g data-detail="bearing-ball-cage">${bearingBalls}</g><circle cx="${cx}" cy="${cy}" r="16.2" fill="url(#metal)" stroke="#f8fafc" stroke-width=".72"/><circle cx="${cx}" cy="${cy}" r="14.6" fill="#06111d" stroke="${accent}" stroke-width="1.05"/><polygon data-detail="octagonal-rotor" points="${rotor}" fill="url(#dark-metal)" stroke="#e2e8f0" stroke-width=".8"/><circle data-detail="keyed-drive-coupler" cx="${cx}" cy="${cy}" r="10.1" fill="#020617" stroke="${secondary}" stroke-width="1.05"/><circle data-detail="axial-retainer" cx="${cx}" cy="${cy}" r="8.55" fill="none" stroke="#cbd5e1" stroke-width=".42" stroke-dasharray="2.2 1.4"/><polygon data-detail="drive-shaft-spline" points="${shaftSpline}" fill="url(#metal)" stroke="${accent}" stroke-width=".66"/><polygon data-detail="hexagonal-aperture" points="${aperture}" fill="#020409" stroke="${secondary}" stroke-width=".72"/><circle data-detail="hardened-shaft-cap" cx="${cx}" cy="${cy}" r="2.25" fill="url(#screw-metal)" stroke="#f8fafc" stroke-width=".46"/><path data-detail="shaft-keyway" d="M${cx} ${cy - 7.1}v3.4h2.1" fill="none" stroke="#020409" stroke-width=".85" stroke-linecap="round"/><path d="M${cx - 1.1} ${cy - 1.15}h2.2" stroke="${secondary}" stroke-width=".48"/><circle cx="${cx - .7}" cy="${cy - .8}" r=".5" fill="#fff" opacity=".78"/></g></g>`;
}

function refineHeavyStrokes(markup) {
  return markup.replace(/stroke-width="(\d+(?:\.\d+)?)"/g, (match, rawWidth) => {
    const width = Number(rawWidth);
    if (width < 2.4) return match;
    const refined = width >= 12 ? width - 7.6 : width >= 9 ? width - 5.7 : width >= 7 ? width - 4.65 : width >= 5 ? width - 3.25 : width >= 3.2 ? width - 1.35 : width - .5;
    return `stroke-width="${Number(refined.toFixed(2))}"`;
  });
}

